class NomTipoVehiculo extends BaseNomTipoVehiculo
{

    public function setUp()
    {
        parent::setUp();
    }

    public function getTiposVehiculos($post){

        Try{
            $query = Doctrine_Query::create()->from('NomTipoVehiculo o');
            $cont = Doctrine_Query::create()->from('NomTipoVehiculo o');
            if($post['denominacion']!='' && $post['denominacion']!=null){
                $query->addWhere("o.nombre ILIKE '%".$post['denominacion']."%'");
                $cont->addWhere("o.nombre ILIKE '%".$post['denominacion']."%'");
            }
            $resp = $query->offset($post['start'])->limit($post['limit'])->fetchArray();
            $cant = $cont->count();
        }catch (Exception $e){
            print($e);
        }

        return array('data'=>$resp, 'total'=>$cant);
//        return $res;
    }

}
